// HighLevel (GoHighLevel) on a private integration token: every operation of HighLevel's API v2/v3 that a token can
// call. actions.json is generated by `bun scripts/openapi-actions.ts gohighlevel`; webhooks need a Marketplace app,
// so its triggers are polled (polls/gohighlevel.ts).
import { AppsError } from "../../types";
import type { OwnApp } from "../index";
import { type Api, call, specActions } from "../openapi";

// "<token> <location id>" for a sub-account; the token alone for an agency (then each call names its locationId)
export function parseKey(key: string) {
  const [token = "", location] = key.trim().split(/[\s,;|]+/);
  return { token, location };
}

const api: Api = {
  name: "HighLevel",
  base: "https://services.leadconnectorhq.com",
  tokenHelp: "Settings → Private Integrations in HighLevel",
  // each call names the API version it was written for (the generator kept it as __version)
  auth: (key, input) => ({ Authorization: `Bearer ${parseKey(key).token}`, Version: input.__version ?? "2021-07-28", Accept: "application/json" }),
  // HighLevel also answers 401 for a scope the token wasn't given, or a route private tokens can't use: that's no reason to reconnect
  deadToken: (status, body) => status === 401 && !/scope|iam|not yet supported|location|access to/i.test(String(body?.message ?? "")),
};

type Generated = { name: string; version?: string; input: { properties: Record<string, unknown> } };
const file = new URL("./actions.json", import.meta.url);
const actions = await specActions(file, api);
for (const a of (await Bun.file(file).json()).actions as Generated[]) {
  const action = actions[a.name]!;
  const run = action.run;
  const has = (f: string) => f in a.input.properties;
  action.run = (input: Record<string, unknown>, key) => {
    const { location } = parseKey(key);
    const i: Record<string, unknown> = { ...input, __version: a.version ?? "2021-07-28" };
    // the connected sub-account, wherever the call asks for one and the agent left it out
    if (location) {
      for (const f of ["locationId", "location_id"]) if (has(f) && i[f] === undefined) i[f] = location;
      if (has("altId") && i.altId === undefined && (i.altType ?? "location") === "location") i.altId = location;
    }
    if (has("altType") && i.altType === undefined && i.altId !== undefined) i.altType = "location";
    return run(i, key);
  };
}

export const gohighlevel: OwnApp = {
  app: "gohighlevel",
  name: "HighLevel",
  logo: "/logos/gohighlevel.svg",
  keyField: {
    label: "Private integration token and Location ID",
    help: "In your HighLevel sub-account: Settings → Private Integrations → Create new integration, name it Emplio, tick every scope Emplio should use (all of them lets it do everything), and copy the token. Then Settings → Business Profile, copy the Location ID. For a whole agency, use an agency private integration token and leave the Location ID empty.",
    placeholder: "pit-xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx  AbCdEf123456",
    sep: " ",
    parts: [{label:"Private integration token",secret:true,placeholder:"pit-xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"},{label:"Location ID",optional:true,placeholder:"AbCdEf123456"}],
  },
  async check(key) {
    const { token, location } = parseKey(key);
    if (!token) throw new AppsError("Paste the private integration token from HighLevel (Settings → Private Integrations)");
    if (location) {
      const out = (await actions.get_location!.run({ locationId: location }, key)) as { location?: { name?: string } };
      return out.location?.name || location;
    }
    // agency token: one sub-account is enough to know it works
    await actions.search_locations!.run({ limit: 1 }, key);
    return "HighLevel agency";
  },
  actions,
};
